import { createHash } from "node:crypto";

export function buildJwtMessage(appId: string): string {
  const header = Buffer.from(
    JSON.stringify({ alg: "RS256", typ: "JWT" })
  ).toString("base64url");
  const now = Math.floor(Date.now() / 1000);
  const payload = Buffer.from(
    JSON.stringify({ iat: now - 60, exp: now + 180, iss: appId })
  ).toString("base64url");
  return `${header}.${payload}`;
}

export async function signWithKms(
  kmsKeyName: string,
  message: string,
  accessToken: string
): Promise<string> {
  const digest = createHash("sha256").update(message).digest("base64");
  const res = await fetch(
    `https://cloudkms.googleapis.com/v1/${kmsKeyName}:asymmetricSign`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ digest: { sha256: digest } }),
    }
  );
  if (!res.ok)
    throw new Error(`KMS signing failed: ${res.status} ${await res.text()}`);
  const { signature } = (await res.json()) as { signature: string };
  return signature;
}

export function buildJwt(message: string, signature: string): string {
  return `${message}.${Buffer.from(signature, "base64").toString("base64url")}`;
}
